{
  "name": "SR830 锁相放大器",
  "name_en": "SR830 Lock-In Amplifier",
  "manufacturer": "Stanford Research Systems",
  "description": "用于微弱交流信号相敏检测的锁相放大器，可配置参考源、频率、谐波、灵敏度、时间常数、输入耦合与滤波，并支持辅助模拟输入输出、自动增益/相位调整以及内部数据缓冲采集。",
  "description_en": "A lock-in amplifier for phase-sensitive detection of weak AC signals. It supports configuring the reference source, frequency, harmonic, sensitivity, time constant, input coupling, and filtering, and provides auxiliary analog I/O, auto gain/phase functions, and internal buffered data acquisition.",
  "tag_hints": [
    "lock-in amplifier",
    "phase-sensitive detection",
    "AC signal measurement",
    "reference frequency control",
    "time constant filtering",
    "auxiliary analog I/O",
    "buffered data acquisition",
    "SRS SR830"
  ],
  "actions": [
    {
      "action_name": "auto-reference_phase_shift",
      "description": "获取或设置参考相位偏移。",
      "description_en": "Get or set the reference phase shift."
    },
    {
      "action_name": "auto-reference_internal",
      "description": "获取或设置参考源模式。",
      "description_en": "Get or set the reference source mode."
    },
    {
      "action_name": "auto-frequency",
      "description": "获取或设置参考频率。",
      "description_en": "Get or set the reference frequency."
    },
    {
      "action_name": "auto-reference_trigger",
      "description": "获取或设置外部参考模式下的参考触发方式。",
      "description_en": "Get or set the reference trigger mode when using external reference."
    },
    {
      "action_name": "auto-harmonic",
      "description": "获取或设置检测谐波。",
      "description_en": "Get or set the detection harmonic."
    },
    {
      "action_name": "auto-sine_output_amplitude",
      "description": "获取或设置信号正弦输出幅度。",
      "description_en": "Get or set the sine output amplitude."
    },
    {
      "action_name": "auto-input_configuration",
      "description": "获取或设置信号输入配置。",
      "description_en": "Get or set the input configuration."
    },
    {
      "action_name": "auto-input_shield",
      "description": "获取或设置输入屏蔽接地方式。",
      "description_en": "Get or set the input shield grounding mode."
    },
    {
      "action_name": "auto-input_coupling",
      "description": "获取或设置信号输入耦合方式。",
      "description_en": "Get or set the input coupling."
    },
    {
      "action_name": "auto-input_filter",
      "description": "获取或设置输入线路陷波滤波器。",
      "description_en": "Get or set the input line notch filter."
    },
    {
      "action_name": "auto-sensitivity",
      "description": "获取或设置灵敏度。",
      "description_en": "Get or set the sensitivity."
    },
    {
      "action_name": "auto-reserve_mode",
      "description": "获取或设置储备模式。",
      "description_en": "Get or set the reserve mode."
    },
    {
      "action_name": "auto-time_constants",
      "description": "获取或设置时间常数。",
      "description_en": "Get or set the time constant."
    },
    {
      "action_name": "auto-filter_db_per_oct",
      "description": "获取或设置滤波滚降斜率（dB/倍频程）。",
      "description_en": "Get or set the filter roll-off in dB per octave."
    },
    {
      "action_name": "auto-sync_filter",
      "description": "获取或设置同步滤波器状态。",
      "description_en": "Get or set the synchronous filter status."
    },
    {
      "action_name": "auto-display",
      "description": "获取或设置前面板显示通道的数据源。",
      "description_en": "Get or set the front-panel display source for a channel."
    },
    {
      "action_name": "auto-front_output",
      "description": "获取或设置前面板输出通道的数据源。",
      "description_en": "Get or set the front-panel output source for a channel."
    },
    {
      "action_name": "auto-analog_input",
      "description": "读取辅助模拟输入电压。",
      "description_en": "Read the auxiliary analog input voltage."
    },
    {
      "action_name": "auto-analog_output",
      "description": "获取或设置辅助模拟输出电压。",
      "description_en": "Get or set the auxiliary analog output voltage."
    },
    {
      "action_name": "auto-remote",
      "description": "设置前面板锁定状态。",
      "description_en": "Set the front-panel lock state."
    },
    {
      "action_name": "auto-key_click_enabled",
      "description": "获取或设置按键音状态。",
      "description_en": "Get or set the key-click state."
    },
    {
      "action_name": "auto-alarm_enabled",
      "description": "获取或设置报警功能状态。",
      "description_en": "Get or set the alarm state."
    },
    {
      "action_name": "auto-recall_state",
      "description": "从指定非易失存储位置恢复仪器状态。",
      "description_en": "Recall the instrument state from the specified non-volatile memory location."
    },
    {
      "action_name": "auto-save_state",
      "description": "将当前仪器状态保存到指定非易失存储位置。",
      "description_en": "Save the current instrument state to the specified non-volatile memory location."
    },
    {
      "action_name": "auto-wait_bit1",
      "description": "等待自动功能完成信号。",
      "description_en": "Wait for the auto-function completion signal."
    },
    {
      "action_name": "auto-auto_gain_async",
      "description": "异步启动自动增益调整。",
      "description_en": "Start auto gain adjustment asynchronously."
    },
    {
      "action_name": "auto-auto_gain",
      "description": "执行自动增益调整。",
      "description_en": "Perform auto gain adjustment."
    },
    {
      "action_name": "auto-auto_reserve_async",
      "description": "异步启动自动储备调整。",
      "description_en": "Start auto reserve adjustment asynchronously."
    },
    {
      "action_name": "auto-auto_reserve",
      "description": "执行自动储备调整。",
      "description_en": "Perform auto reserve adjustment."
    },
    {
      "action_name": "auto-auto_phase_async",
      "description": "异步启动自动相位调整。",
      "description_en": "Start auto phase adjustment asynchronously."
    },
    {
      "action_name": "auto-auto_phase",
      "description": "执行自动相位调整。",
      "description_en": "Perform auto phase adjustment."
    },
    {
      "action_name": "auto-auto_offset_async",
      "description": "异步启动通道自动归零偏置。",
      "description_en": "Start automatic channel offset-to-zero asynchronously."
    },
    {
      "action_name": "auto-auto_offset",
      "description": "执行自动归零偏置。",
      "description_en": "Perform automatic offset-to-zero."
    },
    {
      "action_name": "auto-sample_rate",
      "description": "获取或设置缓冲采样率。",
      "description_en": "Get or set the buffer sample rate."
    },
    {
      "action_name": "auto-single_shot",
      "description": "获取或设置缓冲区单次采集模式。",
      "description_en": "Get or set the buffer single-shot mode."
    },
    {
      "action_name": "auto-trigger",
      "description": "发送软件触发。",
      "description_en": "Issue a software trigger."
    },
    {
      "action_name": "auto-trigger_start_mode",
      "description": "获取或设置触发启动模式。",
      "description_en": "Get or set the trigger start mode."
    },
    {
      "action_name": "auto-start_data_storage",
      "description": "开始或继续数据存储。",
      "description_en": "Start or resume data storage."
    },
    {
      "action_name": "auto-pause_data_storage",
      "description": "暂停数据存储。",
      "description_en": "Pause data storage."
    },
    {
      "action_name": "auto-reset_data_storage",
      "description": "重置并清空数据缓冲区。",
      "description_en": "Reset and clear the data buffers."
    },
    {
      "action_name": "auto-analog_value",
      "description": "读取指定键对应的模拟量值。",
      "description_en": "Read the analog value for the specified key."
    },
    {
      "action_name": "auto-measure",
      "description": "测量指定通道的数据。",
      "description_en": "Measure the specified channels."
    },
    {
      "action_name": "auto-buffer_length",
      "description": "读取当前缓冲区长度。",
      "description_en": "Read the current buffer length."
    },
    {
      "action_name": "auto-read_buffer",
      "description": "读取指定通道缓冲区中的数据点。",
      "description_en": "Read stored data points from the specified channel buffer."
    }
  ]
}

